#!/usr/bin/env python3
"""Generates the band-limited saw tables (src/synth/saw_tables.h/.cpp).

Same idea as PRA32-U2's oscillator tables, kept to what the saw needs:
one table per band of BAND_SEMITONES notes, each holding only the harmonics
that stay below F_MAX at the band's highest note (so nothing aliases), and
longer tables for the bands with many harmonics (so linear interpolation
stays clean). Each table has one guard sample at the end for the lerp.

    python3 tools/gen_saw_tables.py
"""

import math
import os

import numpy as np

SAMPLE_RATE = 48000
F_MAX = 20000.0          # highest harmonic kept, below Nyquist (24 kHz)
BAND_SEMITONES = 3
NOTE_TOP = 132           # bands cover notes 0 .. NOTE_TOP - 1
MIN_BITS, MAX_BITS = 8, 11
SAMPLES_PER_TOP_HARMONIC = 8
PEAK = 0.98              # the highest sample of any table, relative to int16 full scale

OUT_DIR = os.path.join(os.path.dirname(__file__), "..", "src", "synth")


def note_to_hz(note):
    return 440.0 * 2.0 ** ((note - 69) / 12.0)


def make_band(band):
    f_top = note_to_hz((band + 1) * BAND_SEMITONES)
    harmonics = max(1, int(F_MAX // f_top))
    bits = math.ceil(math.log2(harmonics * SAMPLES_PER_TOP_HARMONIC))
    bits = min(max(bits, MIN_BITS), MAX_BITS)
    harmonics = min(harmonics, (1 << bits) // SAMPLES_PER_TOP_HARMONIC)

    n = 1 << bits
    x = 2.0 * np.pi * np.arange(n) / n
    k = np.arange(1, harmonics + 1)
    # Rising saw from -1 to +1: (2/pi) * sum (-1)^(k+1) sin(kx) / k, phase-shifted
    # so that the ramp starts at the bottom (the drop sits at the end of the table)
    wave = -(2.0 / np.pi) * (np.sin(np.outer(x, k)) / k).sum(axis=1)
    return bits, harmonics, np.append(wave, wave[0])


def to_int16(tables):
    # One scale for all bands, so the level does not jump between them. The Gibbs
    # overshoot of a band-limited saw is ~18% of its swing, so peaks reach ~1.18.
    peak = max(np.abs(w).max() for _, _, w in tables)
    scale = PEAK * 32767 / peak
    out = []
    for bits, harmonics, wave in tables:
        q = np.round(wave * scale)
        assert np.abs(q).max() <= 32767, "table would overflow int16"
        out.append((bits, harmonics, q.astype(np.int16)))
    print(f"peak {peak:.3f}: a full ramp spans +/-{scale / 32768:.3f}")
    global RAMP_AMPLITUDE
    RAMP_AMPLITUDE = scale / 32768.0
    return out


def main():
    bands = NOTE_TOP // BAND_SEMITONES
    tables = to_int16([make_band(b) for b in range(bands)])
    # The lowest bands all hit the harmonic cap and come out identical: store one copy
    array_of = []
    for b, (bits, harmonics, _) in enumerate(tables):
        same = [a for a in range(b) if tables[a][:2] == (bits, harmonics)]
        array_of.append(array_of[same[0]] if same else b)
    total_bytes = sum(tables[b][2].size * 2 for b in set(array_of))

    with open(os.path.join(OUT_DIR, "saw_tables.h"), "w") as h:
        h.write(
            "// Generated by tools/gen_saw_tables.py - do not edit\n"
            "#pragma once\n\n"
            "#include <cstdint>\n\n"
            "namespace synth {\n\n"
            "struct SawTable {\n"
            "  const int16_t* data;   // (1 << bits) samples + 1 guard sample\n"
            "  uint8_t bits;\n"
            "};\n\n"
            f"constexpr int kSawBandSemitones = {BAND_SEMITONES};\n"
            f"// A table's ideal ramp (2 phase - 1) is stored scaled by this, so a\n"
            f"// sample / 32768 / kSawRampAmplitude is the saw at +/-1\n"
            f"constexpr float kSawRampAmplitude = {RAMP_AMPLITUDE:.9f}f;\n"
            f"constexpr int kSawBands = {bands};\n\n"
            "extern const SawTable kSawTables[kSawBands];\n\n"
            "}  // namespace synth\n"
        )

    with open(os.path.join(OUT_DIR, "saw_tables.cpp"), "w") as c:
        c.write(
            "// Generated by tools/gen_saw_tables.py - do not edit\n"
            f"// {bands} bands, {total_bytes} bytes of samples\n"
            '#include "synth/saw_tables.h"\n\n'
            '#include "config/platform.h"\n\n'
            "namespace synth {\n\n"
        )
        for b, (bits, harmonics, data) in enumerate(tables):
            if array_of[b] != b:
                continue
            first = b * BAND_SEMITONES
            last = (b + array_of.count(b)) * BAND_SEMITONES - 1
            c.write(f"// notes {first}-{last}: {harmonics} harmonics, {1 << bits} samples\n")
            c.write(f'static const int16_t AUDIO_RAM_DATA("saw_tables") kSaw{b}[] = {{\n')
            for i in range(0, data.size, 16):
                c.write("  " + ", ".join(str(int(v)) for v in data[i:i + 16]) + ",\n")
            c.write("};\n\n")
        c.write('const SawTable AUDIO_RAM_DATA("saw_tables") kSawTables[kSawBands] = {\n')
        for b, (bits, _, _) in enumerate(tables):
            c.write(f"  {{kSaw{array_of[b]}, {bits}}},\n")
        c.write("};\n\n}  // namespace synth\n")

    print(f"{bands} bands, {total_bytes} bytes")


if __name__ == "__main__":
    main()
